$r=Join-Path $PSScriptRoot "reports";$f="GmailReadProfile.json","MessageWindowBuilder.json","CandidateMessageFilter.json","ReadSimulation.json";$ok=0;foreach($i in $f){if(Test-Path (Join-Path $r $i)){$ok++}};$s=if($ok-eq4){"PASS"}else{"FAIL"};@{status=$s;previewOnly=$true;gmailReadsEnabled=$false}|ConvertTo-Json|Set-Content (Join-Path $r "ReadinessSummary.json");if($s-eq"PASS"){Write-Host "[PASS]";exit 0}else{Write-Host "[FAIL]";exit 1}